Create a Generic Plot Function

plot.census &lt;- function(census_tib, num_var, cat_var){

  if(length(num_var) != 1){
    stop("Specify exactly one numeric variable")
  }

  if(length(cat_var) != 1){
    stop("Specify exactly one categorical variable")
  }

  ggplot(census_tib, aes(x = get(cat_var),
      y = get(num_var),weight = PWGTP)) +
    geom_boxplot() +
    labs(title = paste(num_var, "by", cat_var),
      x = cat_var,
      y = num_var
    )
}


